import { test, expect } from '@playwright/test';

test.describe('Filtered Search URL Sharing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should filter search results and generate URL', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'test query');
    await page.click(getByRole('button', { name: 'Filter' }));

    const filteredResults = await page.locator(getByText('Filtered Results')).count();
    expect(filteredResults).toBeGreaterThan(0);

    const currentUrl = page.url();
    expect(currentUrl).toContain('filter=test');
  });

  test('should share the filtered search URL', async ({ page }) => {
    await page.fill(getByLabel('Search'), 'test query');
    await page.click(getByRole('button', { name: 'Filter' }));

    const currentUrl = page.url();
    await page.click(getByRole('button', { name: 'Share' }));

    const sharedUrl = await page.locator(getByText('Shared URL')).innerText();
    expect(sharedUrl).toBe(currentUrl);
  });
});
